from kivy.app import App
from kivy.uix.gridlayout import GridLayout
from kivy.uix.button import Button
from kivy.uix.behaviors.focus import FocusBehavior
from kivy.uix.behaviors.compoundselection import CompoundSelectionBehavior
from kivy.properties import ListProperty
from kivy.core.window import Window
from kivy.utils import get_color_from_hex

class SelectableGrid(FocusBehavior, CompoundSelectionBehavior, GridLayout):
    selected_nodes = ListProperty([])

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._typed_number = ''
        self._typed_number_clock = None
        Window.bind(on_key_down=self.on_key_down, on_key_up=self.on_key_up)
        self.bind(selected_nodes=self.on_selection_change)

    def on_selection_change(self, *args):
        print("Selected nodes:", self.selected_nodes)
        for child in self.children:
            if child.text in self.selected_nodes:
                child.background_color = get_color_from_hex('#3399FF')
            else:
                child.background_color = get_color_from_hex('#FFFFFF')

    def on_key_down(self, window, key, scancode, codepoint, modifiers):
        if codepoint and codepoint.isdigit():
            self._typed_number += codepoint
            self.goto_node_by_number(self._typed_number)
            from kivy.clock import Clock
            if self._typed_number_clock:
                self._typed_number_clock.cancel()
            self._typed_number_clock = Clock.schedule_once(self._clear_typed_number, 1)
            return True
        elif key in (273, 274, 275, 276):  # up, down, right, left
            self.select_with_key_down(key)
            return True
        elif key == 13:  # Enter
            self.apply_selection()
            return True
        return False

    def on_key_up(self, window, key, scancode):
        # Could be used for key up logic if needed
        return False

    def _clear_typed_number(self, *args):
        self._typed_number = ''

    def goto_node_by_number(self, number_str):
        for child in self.children:
            if child.text == number_str:
                self.clear_selection()
                self.select_node(child)
                self.selected_nodes = [child.text]
                break

    def select_node(self, node):
        if node.text not in self.selected_nodes:
            self.selected_nodes.append(node.text)
            self.on_selection_change()

    def deselect_node(self, node):
        if node.text in self.selected_nodes:
            self.selected_nodes.remove(node.text)
            self.on_selection_change()

    def select_with_key_down(self, key):
        # Simple navigation: left/right/up/down
        children = list(reversed(self.children))
        if not self.selected_nodes:
            if children:
                self.select_node(children[0])
            return
        current_idx = None
        for idx, child in enumerate(children):
            if child.text == self.selected_nodes[-1]:
                current_idx = idx
                break
        if current_idx is None:
            return
        cols = self.cols
        rows = self.rows
        if key == 275:  # right
            next_idx = current_idx + 1 if current_idx + 1 < len(children) else current_idx
        elif key == 276:  # left
            next_idx = current_idx - 1 if current_idx - 1 >= 0 else current_idx
        elif key == 273:  # up
            next_idx = current_idx - cols if current_idx - cols >= 0 else current_idx
        elif key == 274:  # down
            next_idx = current_idx + cols if current_idx + cols < len(children) else current_idx
        else:
            next_idx = current_idx
        if next_idx != current_idx:
            self.clear_selection()
            self.select_node(children[next_idx])
            self.selected_nodes = [children[next_idx].text]

    def select_with_touch(self, instance, touch):
        if instance.collide_point(*touch.pos):
            if instance.text in self.selected_nodes:
                self.deselect_node(instance)
            else:
                self.clear_selection()
                self.select_node(instance)
                self.selected_nodes = [instance.text]
            return True
        return False

    def on_touch_down(self, touch):
        for child in self.children:
            if child.collide_point(*touch.pos):
                self.select_with_touch(child, touch)
                return True
        return super().on_touch_down(touch)

    def clear_selection(self):
        self.selected_nodes = []

    def apply_selection(self):
        # Placeholder for any action on selection apply
        pass

class TestApp(App):
    def build(self):
        grid = SelectableGrid(cols=5, rows=8, spacing=5, padding=5, size_hint=(1, 1))
        for i in range(1, 41):
            btn = Button(text=str(i), background_color=get_color_from_hex('#FFFFFF'))
            btn.bind(on_touch_down=lambda instance, touch, btn=btn: grid.select_with_touch(btn, touch))
            grid.add_widget(btn)
        return grid

if __name__ == '__main__':
    TestApp().run()
